import React from 'react';
import {RouteComponentProps, Link, withRouter} from "react-router-dom";
import {MatchProps} from "../interfaces";
import cx from 'classnames';
//import '../mdbootstrap/js/vendor/jarallax';
// @ts-ignore
import {jarallax} from 'jarallax';
import _T from '../lang';

import bs from "../styles/styles.module.scss"
import "../styles/styles.scss";
import homeStyle from './home.module.css';
import * as Waves from "../mdbootstrap/js/vendor/waves";

import Footer from "../footer";

class Home extends React.Component<RouteComponentProps<MatchProps>> {

    componentDidMount() {
        Waves.attach('.'+bs.btn+':not(.'+bs["btn-flat"]+'), .'+bs["btn-floating"], ['waves-light']);
        Waves.attach('.'+bs["btn-flat"], ['waves-effect']);
        Waves.init();
        jarallax(document.querySelectorAll('.jarallax'));
    }

    render() {
            let lang = this.props.match.params.lang;
            return (
                <div>
                    <div className = {cx(homeStyle.jarallax, homeStyle.view) + " jarallax"} data-jarallax='{"speed": 0.2}'>
                        <div className = {cx(homeStyle.mask, homeStyle["rgba-black-light"])} >
                            <div className = {cx(bs.container, bs["h-100"], bs["d-flex"], bs["justify-content-center"], bs["align-items-center"])} >
                                <div className = {cx(bs.row, bs["pt-3"], bs["mt-3"])} >
                                    <div className = {cx(bs["col-md-12"])} >
                                        <div className = {cx(bs["text-center"])} >
                                            <h1 className = {cx(bs["text-uppercase"], bs["font-weight-bold"], bs["mb-3"])} style={{color: "white"}} >
                                                <strong>{_T(lang,"Welcome to AS205088")}</strong></h1>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <main>
                        <div className={cx(bs.container, bs["mt-5"], bs["pt-3"], bs["pb-3"])}>
                            {lang === "zh_CN" &&
                            <div>
                                <h4>简介</h4>
                                <p>本网站包含有关<a href="https://www.kkdev.org">Shelikhoo</a>运营的 ShellNet Network (AS205088) 的信息。 </p>
                                <h4>互联</h4>
                                <p>我们的互联政策是开放的。 您可以通过我们共同的互联网交换中心或通过隧道与我们互联。</p>
                            </div>
                            }
                            {lang === "en" &&
                            <div>
                                <h4>Introduction</h4>
                                <p>This website contains information about the ShellNet Network (AS205088) operated by <a href="https://www.kkdev.org">Shelikhoo</a>.</p>
                                <h4>Peering</h4>
                                <p>We have an open peering policy. You can peer with us through Internet eXchanges that we have in common.</p>
                            </div>
                            }
                        </div>
                    </main>
                    <Footer lang={lang}/>
                </div>
            )
    }
}

export default withRouter(Home);